import { useEffect, useRef, useState } from 'react'
import { X, ExternalLink } from 'lucide-react'
import manualExploded from './teardown/manual-thermoholder-exploded.svg'
import manualAssembled from './teardown/manual-thermoholder-assembled.svg'
import digitalExploded from './teardown/digital-thermoholder-exploded.svg'
import digitalAssembled from './teardown/digital-thermoholder-assembled.svg'

// Generated by tools/teardown (npm run build there); same model as the viewer page.
const SHEETS = {
  Manual: { id: 'manual-thermoholder', exploded: manualExploded, assembled: manualAssembled },
  Digital: { id: 'digital-thermoholder', exploded: digitalExploded, assembled: digitalAssembled },
}

const PARTS = {
  Manual: [
    ['Stainless case', 'Holds the measuring electronics.'],
    ['Face plate', 'Carries the 5 status LEDs and the display opening.'],
    ['Display window', 'Covers the red 7-segment display.'],
    ['Push button', 'Red button beside the unit number.'],
    ['Unit number label', 'The holder number, e.g. 10 or MASTER.'],
  ],
  Digital: [
    ['Rubber housing', 'Shock-absorbing body around the electronics.'],
    ['Face plate', 'Carries the 3 status LEDs and the LCD opening.'],
    ['LCD window', 'Covers the backlit LCD.'],
    ['Keypad', 'Up, down, confirm and cancel keys.'],
    ['Unit number label', 'The holder number sticker.'],
  ],
}
const COMMON = [
  ['Handle', 'Grip under the head.'],
  ['Contact block', 'Square block on the back of the head.'],
  ['Taper', 'Wedge from the contact block down to the lance.'],
  ['Lance', 'Steel tube, straight then bent down at the end (shortened in the drawing).'],
  ['Temtip tube', 'Slim kraft cardboard tube pushed over the lance end.'],
  ['Brass band', 'Ring at the end of the tube.'],
  ['Temtip sensor body', 'Thicker white body holding the thermocouple.'],
  ['Temtip cap', 'Short slim end that is dipped into the molten metal.'],
]

export default function PartsDialog({ holder, onClose }) {
  const [view, setView] = useState('exploded')
  const dialog = useRef(null)
  const sheet = SHEETS[holder.type]
  const viewer = `${import.meta.env.BASE_URL}teardown/thermoholder.html#${sheet.id}`

  useEffect(() => { dialog.current.focus({ preventScroll: true }) }, [])
  useEffect(() => {
    const onKey = (e) => {
      if (e.key !== 'Escape') return
      e.stopImmediatePropagation()
      onClose()
    }
    window.addEventListener('keydown', onKey, true)
    return () => window.removeEventListener('keydown', onKey, true)
  }, [onClose])

  return (
    <div className="fixed inset-0 z-50 bg-slate-900/70 flex items-center justify-center p-2 sm:p-4" onClick={(e) => { e.stopPropagation(); onClose() }}>
      <div
        ref={dialog}
        tabIndex={-1}
        role="dialog"
        aria-modal="true"
        aria-label={`${holder.label} parts`}
        className="bg-white rounded-2xl w-full max-w-6xl max-h-[94vh] overflow-y-auto overflow-x-hidden outline-none [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex flex-wrap items-center gap-3 px-4 sm:px-5 pt-4 pb-2">
          <div>
            <h2 className="text-lg font-bold text-slate-900">{holder.label} · Parts</h2>
            <p className="text-sm text-slate-500">{holder.type} thermoholder, exploded along its lance</p>
          </div>
          <div className="ml-auto flex items-center gap-2">
            <div className="flex gap-1 bg-slate-100 rounded-lg p-1" role="group" aria-label="View">
              {['exploded', 'assembled'].map((v) => (
                <button
                  key={v}
                  onClick={() => setView(v)}
                  aria-pressed={view === v}
                  className={`px-3 py-1.5 rounded-md text-sm font-semibold capitalize touch-target ${view === v ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  {v}
                </button>
              ))}
            </div>
            <button onClick={onClose} aria-label="Close" className="p-1.5 rounded-lg hover:bg-slate-100 text-slate-500">
              <X size={20} />
            </button>
          </div>
        </div>

        <div className="px-2 sm:px-4 overflow-x-auto [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
          <img
            src={sheet[view]}
            alt={`${holder.label}: ${holder.type.toLowerCase()} thermoholder, ${view} view${view === 'exploded' ? ' with every part labelled' : ''}.`}
            className="block w-full min-w-[680px] h-auto select-none"
            draggable={false}
          />
        </div>

        <div className="grid gap-x-8 gap-y-1.5 sm:grid-cols-2 px-4 sm:px-5 py-4 border-t border-slate-200 mt-2 font-serif text-[15px] text-slate-700">
          {[...PARTS[holder.type], ...COMMON].map(([name, text]) => (
            <p key={name}><span className="font-sans text-xs font-semibold uppercase tracking-wider text-slate-500">{name}</span> — {text}</p>
          ))}
        </div>

        <div className="flex flex-wrap items-center gap-3 px-4 sm:px-5 pb-4 text-xs text-slate-500">
          <span>Illustrative drawing: proportions are estimated from photos, internals are not shown.</span>
          <a href={viewer} target="_blank" rel="noopener" className="ml-auto inline-flex items-center gap-1.5 font-sans text-sm font-medium text-blue-700 hover:text-blue-600">
            Open interactive viewer (zoom, colors, SVG / PNG / PDF) <ExternalLink size={14} />
          </a>
        </div>
      </div>
    </div>
  )
}
